 {Synth s;CHECK(bs_abi_version()==7&&bs_parameter_count()==44&&sizeof(bs_patch)==180);bs_patch p{},q{};CHECK(bs_get_patch(s.p,&p));p.values[42]=.75f;p.values[43]=1;CHECK(bs_set_patch(s.p,&p));CHECK(bs_get_patch(s.p,&q));CHECK(std::memcmp(&p,&q,sizeof p)==0);p.values[42]=std::numeric_limits<float>::infinity();CHECK(!bs_set_patch(s.p,&p));bs_patch retained{};bs_get_patch(s.p,&retained);CHECK(std::memcmp(&retained,&q,sizeof q)==0);bs_modulation_config_v3 c{};bs_default_modulation_v3(&c);c.sources[0].enabled=1;c.sources[0].route_count=1;c.sources[0].routes[0]={0,0,BS_FILTER_RESONANCE,.5f};CHECK(bs_set_modulation_v3(s.p,&c));c.sources[0].routes[0].parameter_id=BS_FILTER_MODE;CHECK(!bs_set_modulation_v3(s.p,&c));}
 std::puts("PASS current ABI7, atomic schema, continuous Resonance route and non-routable mode");
 {double worst=0;unsigned cases=0;for(double rate:{8000.,44100.,48000.,96000.,192000.,384000.})for(double cutoff:{rate*.005,rate*.05,rate*.4})for(double resonance:{0.,.5,1.}){blocks_detail::ResonantFilter f;blocks_detail::ResonantCoefficients c;const double q=c.q(resonance);c.set(cutoff,1/q,rate);constexpr unsigned n=65536;std::array<std::complex<double>,3> measured{};const std::array<double,3> frequencies{{cutoff*.25,cutoff,std::min(rate*.49,cutoff*2)}};for(unsigned i=0;i<n;++i){const double y=f.process(i==0?1:0,c);CHECK(std::isfinite(y));for(unsigned j=0;j<3;++j)measured[j]+=y*std::polar(1.,-2*pi*frequencies[j]*i/rate);}for(unsigned j=0;j<3;++j){const auto expected=response(frequencies[j],cutoff,rate,q);const double error=std::abs(measured[j]-expected)/std::max(.01,std::abs(expected));worst=std::max(worst,error);CHECK(error<1e-8);++cases;}}CHECK(std::abs(blocks_detail::ResonantCoefficients::q(1)-8)<1e-12);std::printf("METRIC LP12 impulse complex-response cases=%u maximum relative error=%.10g\n",cases,worst);}
