 {double tail=0,early=0;blocks_detail::ResonantFilter f;blocks_detail::ResonantCoefficients c;c.set(20,1./8,48000);for(unsigned i=0;i<96000;++i){double y=f.process(i==0?1:0,c);if(i<4800)early+=y*y;if(i>=72000)tail+=y*y;}CHECK(tail<early*1e-9);CHECK(f.ic1*f.ic1+f.ic2*f.ic2<1e-14);std::printf("METRIC worst low-cutoff Q8 impulse late/early energy=%.10g\n",tail/early);}
 std::puts("PASS damped resonance rings then decays without self oscillation or residual DC");
 {Synth dry,soft,res;cleanTone(dry.p,0,0,440);cleanTone(soft.p,0,0,440);cleanTone(res.p,1,1,440);bs_set_parameter(dry.p,BS_FILTER_MIX,0);bs_reset(dry.p);auto d=render(dry.p,24000,128,{on(0)}),a=render(soft.p,24000,128,{on(0)}),b=render(res.p,24000,128,{on(0)});const double ratio=rms(b,12000)/rms(d,12000);CHECK(std::abs(ratio-8)<.03);CHECK(rms(b,12000)>rms(a,12000)*10);std::printf("METRIC actual-core resonant440Hz Q8 gain=%.7f (fixed low input/output gains)\n",ratio);}
