 std::puts("PASS mode fade retarget continuity and exact return to continuously warmed Soft state");
 {unsigned cases=0;double maximum=0;for(double rate:{8000.,44100.,48000.,96000.,192000.,384000.}){Synth a(rate),b(rate);for(auto*s:{a.p,b.p}){bs_set_parameter(s,BS_FILTER_MODE,1);bs_set_parameter(s,BS_FILTER_RESONANCE,1);bs_set_parameter(s,BS_FILTER_AMOUNT,48);bs_set_parameter(s,BS_FILTER_ATTACK,.001f);bs_set_parameter(s,BS_FILTER_DECAY,.001f);bs_set_parameter(s,BS_FILTER_SUSTAIN,0);bs_set_parameter(s,BS_FILTER_RELEASE,.001f);bs_set_parameter(s,BS_ATTACK,.001f);bs_set_parameter(s,BS_RELEASE,.001f);bs_modulation_config_v3 c{};bs_default_modulation_v3(&c);c.sources[0].enabled=1;c.sources[0].waveform=BS_LFO_SQUARE;c.sources[0].rate_hz=20;c.sources[0].intensity=1;c.sources[0].route_count=2;c.sources[0].routes[0]={0,0,BS_CUTOFF,1};c.sources[0].routes[1]={0,0,BS_FILTER_RESONANCE,1};CHECK(bs_set_modulation_v3(s,&c));bs_reset(s);}std::vector<bs_event>events;for(unsigned i=0;i<16;++i)events.push_back(on(0,36+i*4));for(unsigned t=97;t<unsigned(rate*.2);t+=137){events.push_back(param(t,BS_CUTOFF,(t/137)%2?20:20000));events.push_back(param(t,BS_FILTER_MODE,(t/137)%3?1:0));}const unsigned panic=unsigned(rate*.22);events.push_back({panic,BS_PANIC,0,0,0,0});auto x=render(a.p,unsigned(rate*.25),1,events),y=render(b.p,unsigned(rate*.25),128,events);same(x,y);CHECK(bs_active_voices(a.p)==0);for(unsigned i=0;i<x.l.size();++i){maximum=std::max(maximum,std::abs(double(x.l[i])));if(i>=panic)CHECK(x.l[i]==0&&x.r[i]==0);}++cases;}CHECK(allocations==0);std::printf("METRIC fast-modulation rates=%u stereo peak=%.8f allocations=%u\n",cases,maximum,allocations);}
